//
//  DUME_Production_Reconciled.swift
//  Simplified Unified Drift Fix Layer
//

import Foundation
import Accelerate
import CryptoKit
import Atomics

// =====================================================
// MARK: - 1. ADAPTIVE METRIC (REPLACES STATIC DISTANCE)
// =====================================================

public protocol DUMEMetric {
    func transform(_ v: [Float]) -> [Float]
    func distance(_ a: [Float], _ b: [Float]) -> Float
}

/// Normalized cosine-space metric (stable under drift)
public struct CosineMetric: DUMEMetric {

    public init() {}

    public func transform(_ v: [Float]) -> [Float] {
        let norm = sqrt(v.reduce(0) { $0 + $1 * $1 })
        guard norm > 0 else { return v }
        return v.map { $0 / norm }
    }

    public func distance(_ a: [Float], _ b: [Float]) -> Float {
        let aN = transform(a)
        let bN = transform(b)

        var dot: Float = 0
        vDSP_dotpr(aN, 1, bN, 1, &dot, vDSP_Length(aN.count))

        return 1 - dot
    }
}

// =====================================================
// MARK: - 2. CONTEXT-AWARE COMPRESSION
// =====================================================

public struct CompressionContext {
    public let entropy: Float
    public let drift: Float
}

/// Adaptive sparsification based on system state
public struct AdaptiveCompression {

    public init() {}

    public func compress(_ v: [Float], ctx: CompressionContext) -> ([Float], [Int]) {

        let threshold = max(0.005, 0.02 * (1 + ctx.entropy + ctx.drift))

        var values: [Float] = []
        var indices: [Int] = []

        for i in v.indices {
            if abs(v[i]) > threshold {
                values.append(v[i])
                indices.append(i)
            }
        }

        return (values, indices)
    }
}

// =====================================================
// MARK: - 3. OPTIONAL ENCRYPTION LAYER
// =====================================================

public protocol DUMEEncryption {
    func encrypt(_ data: Data) throws -> Data
    func decrypt(_ data: Data) throws -> Data
}

public struct AESGCMEncryption: DUMEEncryption {
    private let key: SymmetricKey

    public init(key: SymmetricKey) {
        self.key = key
    }

    public func encrypt(_ data: Data) throws -> Data {
        let box = try AES.GCM.seal(data, using: key)
        return box.combined ?? Data()
    }

    public func decrypt(_ data: Data) throws -> Data {
        let box = try AES.GCM.SealedBox(combined: data)
        return try AES.GCM.open(box, using: key)
    }
}

// =====================================================
// MARK: - 4. VERSIONED STORAGE (DRIFT SAFE)
// =====================================================

public struct Anchor {
    public let id: String
    public let vector: [Float]
    public let version: Int
}

public protocol Storage {
    func put(_ a: Anchor)
    func get(_ id: String) -> Anchor?
}

/// Minimal thread-safe in-memory store
public final class MemoryStorage: Storage {

    private var data: [String: Anchor] = [:]
    private let lock = NSLock()

    public init() {}

    public func put(_ a: Anchor) {
        lock.lock(); defer { lock.unlock() }

        if let existing = data[a.id], existing.version > a.version {
            return
        }

        data[a.id] = a
    }

    public func get(_ id: String) -> Anchor? {
        lock.lock(); defer { lock.unlock() }
        return data[id]
    }
}

// =====================================================
// MARK: - 5. CORE EXECUTION ENGINE
// =====================================================

public final class DUMEEngine {

    private let metric: DUMEMetric
    private let storage: Storage
    private let compression: AdaptiveCompression
    private let crypto: DUMEEncryption?

    public init(
        metric: DUMEMetric,
        storage: Storage,
        compression: AdaptiveCompression,
        crypto: DUMEEncryption? = nil
    ) {
        self.metric = metric
        self.storage = storage
        self.compression = compression
        self.crypto = crypto
    }

    // -----------------------------
    // INGEST PIPELINE
    // -----------------------------

    public func ingest(id: String, vector: [Float], ctx: CompressionContext) {

        let (values, indices) = compression.compress(vector, ctx: ctx)

        let raw = Data(bytes: values, count: values.count * MemoryLayout<Float>.size)

        let secured: Data
        if let crypto = crypto {
            secured = try! crypto.encrypt(raw)
        } else {
            secured = raw
        }

        let restored = secured.withUnsafeBytes {
            Array($0.bindMemory(to: Float.self))
        }

        var full = [Float](repeating: 0, count: vector.count)
        for (i, idx) in indices.enumerated() {
            if i < restored.count {
                full[idx] = restored[i]
            }
        }

        storage.put(
            Anchor(id: id, vector: full, version: 1)
        )
    }

    // -----------------------------
    // RETRIEVAL PIPELINE
    // -----------------------------

    public func retrieve(id: String) -> [Float]? {
        guard let a = storage.get(id) else { return nil }
        return a.vector
    }
}

// =====================================================
// MARK: - 6. FACTORY (SINGLE ENTRY POINT)
// =====================================================

public enum DUMEFactory {

    public static func build() -> DUMEEngine {

        let key = SymmetricKey(size: .bits256)

        return DUMEEngine(
            metric: CosineMetric(),
            storage: MemoryStorage(),
            compression: AdaptiveCompression(),
            crypto: AESGCMEncryption(key: key)
        )
    }
}
