### **11. Sources/Engine/DUMEHybridEngine.swift**

```swift
import Foundation
import CryptoKit

public final class DUMEHybridEngine {
    private let metric: DUMEMetric
    private let storage: any DUMEPersistentStorage
    private let crypto: (any DUMEEncryption)?
    private let compression: SparseCompression
    private let speculator: SpeculativeEngine

    private var phase: SystemPhase = .coldStart
    private var ingestCount: Int = 0
    private let warmupTarget: Int = 100

    private var graph: GraphEvolution
    private var burstDetector: BurstDetector

    private let enableEvolution: Bool
    private let enableSpeculation: Bool
    private let enableBurstProtection: Bool
    private let compressionThreshold: Float

    public init(
        metric: DUMEMetric,
        storage: any DUMEPersistentStorage,
        crypto: (any DUMEEncryption)? = nil,
        compression: SparseCompression = SparseCompression(),
        speculator: SpeculativeEngine = SpeculativeEngine(),
        enableEvolution: Bool = true,
        enableSpeculation: Bool = true,
        enableBurstProtection: Bool = true,
        compressionThreshold: Float = 0.02
    ) {
        self.metric = metric
        self.storage = storage
        self.crypto = crypto
        self.compression = compression
        self.speculator = speculator
        self.enableEvolution = enableEvolution
        self.enableSpeculation = enableSpeculation
        self.enableBurstProtection = enableBurstProtection
        self.compressionThreshold = compressionThreshold

        self.graph = GraphEvolution(metric: metric, k: 3)
        self.burstDetector = BurstDetector()
    }

    // MARK: - Public API

    public func ingest(id: String, vector: [Float], ctx: CompressionContext) async throws {
        guard !id.isEmpty else {
            throw DUMEError.invalidVector("Cannot ingest anchor with empty ID")
        }
        guard !vector.isEmpty else {
            throw DUMEError.invalidVector("Cannot ingest empty vector")
        }

        // Phase management
        ingestCount += 1
        updatePhase()

        // Burst detection
        if enableBurstProtection {
            burstDetector.update(entropy: ctx.entropy)
        }
        let isBurst = burstDetector.isBurstMode

        // Speculation (only in active phase and not during burst)
        var finalVector = vector
        if enableSpeculation && !isBurst && phase == .active {
            if let nearest = findNearestVector(vector) {
                let velocity = zip(vector, nearest).map { $0 - $1 }
                let result = speculator.speculate(current: nearest, velocity: velocity)
                if result.isValid {
                    finalVector = result.predicted
                }
            }
        }

        // Compression
        let (values, indices) = try compression.compress(
            finalVector,
            entropy: ctx.entropy,
            drift: ctx.drift,
            isBurstMode: isBurst
        )

        // Encryption
        let raw = Data(bytes: values, count: values.count * MemoryLayout<Float>.size)
        let secured = try crypto?.encrypt(raw) ?? raw

        // Reconstruction
        let restored = secured.withUnsafeBytes {
            Array($0.bindMemory(to: Float.self))
        }

        var full = [Float](repeating: 0, count: vector.count)
        for (i, idx) in indices.enumerated() {
            if i < restored.count {
                full[idx] = restored[i]
            }
        }

        // Storage
        let anchor = Anchor(id: id, vector: full, version: ingestCount)
        try await storage.put(anchor)

        // Graph evolution
        if enableEvolution && !isBurst && phase == .active {
            try graph.addNode(id: id, vector: finalVector)
            graph.pruneOldNodes()
        }
    }

    public func retrieve(id: String) async throws -> [Float]? {
        return try await storage.get(id)?.vector
    }

    public func checkpoint() async throws {
        try await storage.checkpoint()
    }

    public func restore() async throws {
        try await storage.restore()
    }

    public var currentPhase: SystemPhase {
        return phase
    }

    // MARK: - Private Helpers

    private func updatePhase() {
        if phase == .coldStart && ingestCount >= warmupTarget {
            phase = .warming
        } else if phase == .warming && ingestCount >= warmupTarget * 2 {
            phase = .active
        }
    }

    private func findNearestVector(_ vector: [Float]) -> [Float]? {
        guard enableEvolution else { return nil }

        let allNodes = graph.getAllNodes()
        guard !allNodes.isEmpty else { return nil }

        var nearest: [Float]?
        var minDistance = Float.infinity

        for node in allNodes {
            let distance = metric.distance(vector, node.vector)
            if distance < minDistance {
                minDistance = distance
                nearest = node.vector
            }
        }

        return nearest
    }
}
