            drift: Float.random(in: 0.02...0.1)
        )

        try await engine.ingest(id: "vector_\(batch)", vector: vector, ctx: ctx)

        if (batch + 1) % 100 == 0 {
            print("  Ingested \(batch + 1)/\(batchSize) vectors")
        }
    }

    let elapsed = Date().timeIntervalSince(start)
    let rate = Double(batchSize) / elapsed

    print("\n✓ Throughput: \(String(format: "%.0f", rate)) vectors/second")
    print("Total time: \(String(format: "%.2f", elapsed))s")
}

