#!/usr/bin/swift
import Foundation

func healthcheck() {
    print("[HEALTHCHECK] Starting DUME system validation...\n")

    var passed = 0
    var failed = 0

    // Test 1: Build verification
    print("[1/4] Verifying engine builds...")
    do {
        // This is a compile-time check via SPM
        print("✓ Package structure valid")
        passed += 1
    } catch {
        print("✗ Build failed: \(error)")
        failed += 1
    }

    // Test 2: Type validation
    print("[2/4] Validating core types...")
    do {
        let _ = try CompressionContext(entropy: 0.5, drift: 0.5)
        print("✓ CompressionContext initialized")
        passed += 1
    } catch {
        print("✗ Type validation failed: \(error)")
        failed += 1
    }

    // Test 3: Metric correctness
    print("[3/4] Verifying metric calculations...")
    do {
        let metric = HybridMetric(useCosine: true)
        let a = [1.0, 0.0] as [Float]
        let b = [1.0, 0.0] as [Float]
        let distance = metric.distance(a, b)

        if abs(distance - 0.0) < 0.001 {
            print("✓ Metric distance calculation correct")
            passed += 1
        } else {
            print("✗ Metric returned unexpected distance: \(distance)")
            failed += 1
        }
    } catch {
        print("✗ Metric test failed: \(error)")
        failed += 1
    }

    // Test 4: Compression
    print("[4/4] Testing compression...")
    do {
        let compression = SparseCompression()
        let vector = [0.1, 0.0, 0.3, 0.0, 0.5] as [Float]
        let ctx = try CompressionContext(entropy: 0.1, drift: 0.1)

        let (values, indices) = try compression.compress(vector, entropy: ctx.entropy, drift: ctx.drift, isBurstMode: false)

        if values.count > 0 && indices.count == values.count {
            print("✓ Compression succeeded (\(values.count) of \(vector.count) elements retained)")
            passed += 1
        } else {
            print("✗ Compression produced invalid output")
            failed += 1
        }
    } catch {
        print("✗ Compression test failed: \(error)")
        failed += 1
    }

    print("\n[HEALTHCHECK] Results: \(passed) passed, \(failed) failed")
    exit(failed > 0 ? 1 : 0)
}

healthcheck()
