import Foundation
import CryptoKit

public struct AESGCMEncryption: DUMEEncryption {
    private let key: SymmetricKey

    public init(key: SymmetricKey) {
        self.key = key
    }

    public func encrypt(_ data: Data) throws -> Data {
        do {
            let sealedBox = try AES.GCM.seal(data, using: key)
            guard let combined = sealedBox.combined else {
                throw DUMEError.encryptionFailed("Failed to combine sealed box")
            }
            return combined
        } catch {
            throw DUMEError.encryptionFailed("AES-GCM encryption failed: \(error.localizedDescription)")
        }
    }

    public func decrypt(_ data: Data) throws -> Data {
        do {
            let sealedBox = try AES.GCM.SealedBox(combined: data)
            return try AES.GCM.open(sealedBox, using: key)
        } catch {
            throw DUMEError.decryptionFailed("AES-GCM decryption failed: \(error.localizedDescription)")
        }
    }
}

public struct NoOpEncryption: DUMEEncryption {
    public init() {}

    public func encrypt(_ data: Data) throws -> Data {
        return data
    }

    public func decrypt(_ data: Data) throws -> Data {
        return data
    }
}
