import Foundation

public struct GraphEvolution {
    private var nodes: [String: ManifoldNode] = [:]
    private let k: Int
    private let metric: DUMEMetric
    private let utilityDecayInterval: TimeInterval = 3600

    public init(metric: DUMEMetric, k: Int = 3) {
        self.metric = metric
        self.k = max(1, k)
    }

    public mutating func addNode(id: String, vector: [Float]) throws {
        guard !id.isEmpty else {
            throw DUMEError.invalidVector("Cannot add node with empty ID")
        }
        guard !vector.isEmpty else {
            throw DUMEError.invalidVector("Cannot add node with empty vector")
        }

        var newNode = ManifoldNode(id: id, vector: vector)

        let candidates = findNearestNeighbors(vector, exclude: id)
        newNode.neighbors = Set(candidates.prefix(k).map { $0.0 })

        for (neighborId, _) in candidates.prefix(k) {
            if nodes[neighborId] != nil {
                nodes[neighborId]?.neighbors.insert(id)
            }
        }

        nodes[id] = newNode
    }

    public mutating func pruneOldNodes() {
        let now = Date()
        var toRemove: [String] = []

        for (id, var node) in nodes {
            let age = now.timeIntervalSince(node.lastAccess)
            node.decayUtility(age: age)

            if node.utility < 0.1 {
                toRemove.append(id)
            } else {
                nodes[id] = node
            }
        }

        for id in toRemove {
            removeNode(id)
        }
    }

    public func getNode(_ id: String) -> ManifoldNode? {
        return nodes[id]
    }

    public func getAllNodes() -> [ManifoldNode] {
        return Array(nodes.values)
    }

    private func findNearestNeighbors(_ vector: [Float], exclude: String) -> [(String, Float)] {
        var candidates: [(String, Float)] = []

        for (id, node) in nodes where id != exclude {
            let distance = metric.distance(vector, node.vector)
            candidates.append((id, distance))
        }

        candidates.sort { $0.1 < $1.1 }
        return candidates
    }

    private mutating func removeNode(_ id: String) {
        nodes.removeValue(forKey: id)

        for (nid, var node) in nodes {
            node.neighbors.remove(id)
            nodes[nid] = node
        }
    }
}
