import Foundation
import CryptoKit

public enum DUMEHybridFactory {
    public static func build(
        enableEvolution: Bool = true,
        enableSpeculation: Bool = true,
        enableBurstProtection: Bool = true,
        enableCrypto: Bool = true,
        persistenceURL: URL? = nil
    ) -> DUMEHybridEngine {

        let storage: any DUMEPersistentStorage
        if let url = persistenceURL {
            storage = FileStorage(fileURL: url)
        } else {
            storage = InMemoryStorage()
        }

        let crypto: (any DUMEEncryption)? = enableCrypto ? 
            AESGCMEncryption(key: SymmetricKey(size: .bits256)) : 
            nil

        return DUMEHybridEngine(
            metric: HybridMetric(useCosine: true),
            storage: storage,
            crypto: crypto,
            compression: SparseCompression(),
            speculator: SpeculativeEngine(),
            enableEvolution: enableEvolution,
            enableSpeculation: enableSpeculation,
            enableBurstProtection: enableBurstProtection,
            compressionThreshold: 0.02
        )
    }
}
