            print("✓ Metric distance calculation correct")
            passed += 1
        } else {
            print("✗ Metric returned unexpected distance: \(distance)")
            failed += 1
        }
    } catch {
        print("✗ Metric test failed: \(error)")
        failed += 1
    }

    print("[4/4] Testing compression...")
    do {
        let compression = SparseCompression()
        let vector = [0.1, 0.0, 0.3, 0.0, 0.5] as [Float]
        let ctx = try CompressionContext(entropy: 0.1, drift: 0.1)

        let (values, indices) = try compression.compress(vector, entropy: ctx.entropy, drift: ctx.drift, isBurstMode: false)

        if values.count > 0 && indices.count == values.count {
            print("✓ Compression succeeded (\(values.count) of \(vector.count) elements retained)")
            passed += 1
        } else {
            print("✗ Compression produced invalid output")
            failed += 1
        }
    } catch {
